//#region src/shared/types/typeface.d.ts
/**
 * One font file of a {@link CustomTypeface} and the characters it draws, for a face split into files by
 * script, as font CDNs serve them.
 *
 * @group Shared
 */
type CustomTypefaceFile = {
  /** The file's URL, to a format the browser draws text with, such as WOFF2 or TTF. */
  url: string;
  /**
   * The characters the file draws, as CSS `unicode-range` values such as `U+0100-02BA`. List only the
   * ones the file has. A character in the range that the file lacks is drawn in the browser's default
   * sans-serif.
   */
  unicodeRange: string[];
};
/**
 * A typeface of your own for map labels, from font files you host or load from a font CDN. The SDK
 * ships no font, and the map fetches these files itself. Set it for every label on the map through
 * {@link StylingFoundationsModule}, or for one module's labels through their `customTypeface`.
 *
 * Give each weight one file URL, drawing the characters in `unicodeRange`, or a list of
 * {@link CustomTypefaceFile}s with a range each, such as a font CDN's `latin` and `latin-ext` files.
 *
 * @remarks
 * - Each label keeps its weight and slant. A weight with no file takes the file of the nearest weight
 *   given. An italic with none takes the nearest italic given, and the upright file only without one.
 * - Characters outside the files' ranges, and every character of a file that fails to load, are drawn
 *   in the style's own Noto face of the same weight. MapLibre logs a console warning for each file
 *   that fails, with its URL and the reason.
 * - The browser draws the files' text one character cluster at a time. A script whose letters join or
 *   reorder, such as Arabic or Devanagari, reads best left to the style's faces, outside the ranges.
 *
 * @example
 * ```typescript
 * const fraunces = 'https://cdn.jsdelivr.net/fontsource/fonts/fraunces@5/latin';
 * await StylingFoundationsModule.get(map, {
 *   labels: {
 *     customTypeface: {
 *       regular: `${fraunces}-400-normal.woff2`,
 *       bold: `${fraunces}-700-normal.woff2`,
 *       regularItalic: `${fraunces}-400-italic.woff2`,
 *     },
 *   },
 * });
 * ```
 *
 * @group Shared
 */
type CustomTypeface = {
  /** The regular weight, which every role falls back to when no nearer file is given. */
  regular: string | CustomTypefaceFile[];
  /** The medium weight. */
  medium?: string | CustomTypefaceFile[];
  /** The bold weight. */
  bold?: string | CustomTypefaceFile[];
  /** The regular italic. */
  regularItalic?: string | CustomTypefaceFile[];
  /** The medium italic. */
  mediumItalic?: string | CustomTypefaceFile[];
  /** The bold italic. */
  boldItalic?: string | CustomTypefaceFile[];
  /**
   * The characters the files given as a plain URL draw, listed as in
   * {@link CustomTypefaceFile.unicodeRange}.
   *
   * Default: the characters of the `latin` files that Fontsource and Google Fonts serve, which are
   * Basic Latin, Latin-1 and the common punctuation.
   */
  unicodeRange?: string[];
};
