  SHOPPING_GROUP: ("CLOTHING_SHOP" | "CONVENIENCE_STORE" | "DEPARTMENT_STORE" | "ELECTRICAL_APPLIANCES_SHOP" | "FOOD_MARKET" | "GROCERY_STORE" | "HARDWARE_STORE" | "MALL" | "MARKETPLACE" | "SHOP_OR_STORE" | "SUPERMARKET")[];
  TRANSPORTATION_GROUP: ("AIRPORT" | "BUS_STOP" | "FERRY_TERMINAL" | "HELIPORT_OR_HELIPAD" | "PUBLIC_TRANSPORT_STOP" | "RAILWAY_STATION" | "TAXI_STAND")[];
  HEALTH_GROUP: ("DENTIST" | "DOCTOR" | "EMERGENCY_MEDICAL_SERVICE" | "EMERGENCY_ROOM" | "HEALTHCARE_SERVICE" | "HOSPITAL" | "PHARMACY")[];
  PARKING_GROUP: ("OPEN_CAR_PARKING_AREA" | "PARKING_GARAGE")[];
  HOLIDAY_TOURISM_GROUP: ("AMUSEMENT_PARK" | "BEACH" | "HOLIDAY_RENTAL" | "LEISURE_CENTER" | "MOUNTAIN_PASS" | "MOUNTAIN_PEAK" | "MUSEUM" | "NATURAL_FEATURE" | "TOURIST_ATTRACTION" | "TOURIST_INFORMATION" | "VIEWPOINT")[];
  EV_CHARGING_STATIONS_GROUP: "CHARGING_LOCATION"[];
  GAS_STATIONS_GROUP: "FUEL_STATION"[];
  ACCOMMODATION_GROUP: ("CAMPING_GROUND" | "HOLIDAY_RENTAL" | "HOTEL_OR_MOTEL")[];
  ENTERTAINMENT_GROUP: ("CASINO_AND_GAMBLING" | "CINEMA" | "CONCERT_HALL" | "ENTERTAINMENT" | "MOVIE_THEATER" | "NIGHTLIFE" | "THEATER")[];
  SPORTS_LEISURE_GROUP: ("BEACH" | "GOLF_COURSE" | "ICE_RINK" | "LEISURE_CENTER" | "MOUNTAIN_PASS" | "MOUNTAIN_PEAK" | "SPORTS_CENTER" | "STADIUM" | "SWIMMING_POOL" | "WATER_SPORT")[];
  EDUCATION_GROUP: ("COLLEGE_OR_UNIVERSITY" | "CULTURAL_CENTER" | "PUBLIC_LIBRARY" | "SCHOOL")[];
  GOVERNMENT_GROUP: ("COURTHOUSE" | "EMBASSY" | "FIRE_STATION" | "GOVERNMENT_OFFICE" | "POLICE_STATION")[];
