//#region src/pois/types/poisModuleConfig.d.ts
/**
 * Custom icons for the POIs the map style draws, per category.
 *
 * @remarks
 * `categoryIcons` takes the entries {@link PlaceIconConfig.categoryIcons} does, so one list restyles
 * the map's own POIs and the places a {@link PlacesModule} shows. The two differ in two ways: a place
 * takes the entry for its own category first, and only a place takes an entry without an `image`, as
 * the ID of a sprite icon the map already has.
 *
 * @example
 * ```typescript
 * const categoryIcons: CustomImage<MapStylePOICategory>[] = [{ id: 'RESTAURANT', image: restaurantSvg }];
 * await POIsModule.get(map, { icon: { categoryIcons } });
 * await PlacesModule.create(map, { markerType: 'base-map', icon: { categoryIcons } });
 * ```
 *
 * @group POIs
 */
type POIIconConfig = {
  /**
   * An icon per category, drawn in place of the style's own on the POIs of that category.
   *
   * @remarks
   * - The map style knows fewer categories than search does. `CAFE` and `CAFE_PUB` are one category
   *   on the map, so an entry for either reaches both POIs, and the first entry listed wins.
   * - The image is scaled with the style's own icons, `sizeFactor` included, so one the size
   *   of a style POI icon keeps the map's density. `offsetX` and `offsetY` move it.
   * - Entries without an `image` change no POI.
   * - The micro markers of minor POIs keep the style's dots.
   */
  categoryIcons?: NonNullable<PlaceIconConfig['categoryIcons']>;
};
/**
 * A POI category or group to filter by.
 *
 * It is either a specific POI category (like RESTAURANT, HOTEL_OR_MOTEL) or a
 * broader category group (like FOOD_DRINKS_GROUP, SHOPPING_GROUP) that contains
 * multiple related categories.
 *
 * @remarks
 * - Category: Specific POI type (e.g., RESTAURANT, FUEL_STATION)
 * - Group: Collection of related categories (e.g., FOOD_DRINKS_GROUP includes restaurants, cafes, pubs)
 *
 * Groups are more convenient to filter multiple related categories at once.
 *
 * @example
 * ```typescript
 * // Individual category
 * const category: FilterablePOICategory = 'RESTAURANT';
 *
 * // Category group
 * const group: FilterablePOICategory = 'FOOD_DRINKS_GROUP';
 *
 * // Mix of both
 * const categories: FilterablePOICategory[] = ['RESTAURANT', 'SHOPPING_GROUP'];
 * ```
 *
 * @group POIs
 */
