//#region src/shared/AbstractDataOwnedMapModule.d.ts
/**
 * Base class for the map modules that add and own their own GeoJSON sources, layers and images:
 * places, routes, geometries, the traffic overlays and bring-your-own-data.
 *
 * @remarks
 * The module owns the data it draws. Its generated IDs therefore carry a per-instance suffix
 * (see `instanceIndex`), and the module is safely multi-instance. Every `create(map, config?)`
 * call returns another module with its own sources and layers.
 *
 * Owning the data brings the duty this class states. A clean style switch must forget the data
 * the module remembers having shown, through {@link discardShownData}.
 *
 * Every such module hides and shows through {@link setVisible}, which keeps the data it shows.
 *
 * Owning the features also lets it read and write their {@link EventState | event states}.
 * {@link setEventState}, {@link clearEventState}, {@link clearEventStates} and
 * {@link getEventStates} act on the features its `show` takes. Each named scope of its
 * `events` carries the same four over its own part ({@link UserEventsWithStates}). A style change
 * shows again what its sources draw, not the data `show` was given, so the states survive it.
 *
 * @typeParam SOURCES_WITH_LAYERS - The GeoJSON sources, with their layers, this module owns
 * @typeParam CFG - The configuration type for this module, or undefined if no configuration is needed
 *
 * @group Shared
 */
export declare abstract class AbstractDataOwnedMapModule<SOURCES_WITH_LAYERS extends GeoJSONSourcesWithLayers, CFG extends (MapModuleCommonConfig & {
  visible?: boolean;
}) | undefined = undefined> extends AbstractMapModule<SOURCES_WITH_LAYERS, CFG> {
  private readonly eventStates;
  /**
   * Owning the data it draws, such a module always remembers something a clean style switch must
   * forget, so the inherited no-op becomes a duty here. A module that remembers nothing
   * implements this as a no-op, and says why.
   * @protected
   * @ignore
   */
  protected abstract discardShownData(): void;
  /**
   * Shows or hides the layers of everything shown, per `config.visible` and whether each part has
   * data. `config` is passed rather than read, because `_applyConfig` runs before `this.config`
   * holds the new configuration.
   * @protected
   * @ignore
   */
  protected abstract applyVisibility(config: CFG | undefined): void;
  /**
   * Shows or hides everything the module draws.
   *
   * @remarks
   * Stored as `visible` in the configuration. Showing and clearing data never change it. A hidden
   * module keeps its data, through style changes too, and draws it again on `setVisible(true)`.
   *
   * Showing leaves hidden what the configuration turns off: a route section type that is off, the
   * layers a place marker type does not use.
   *
   * @example
   * ```typescript
   * module.setVisible(false);
   * await module.show(data); // stays hidden
   * module.setVisible(true);
   * ```
   */
  setVisible(visible: boolean): void;
  /**
   * Whether the module is set to be shown: its `visible` setting, `true` unless set. A shown
   * module with nothing shown draws nothing. `getShown()` returns what is shown.
   */
  isVisible(): boolean;
  /**
   * The sources drawing the features `show` takes, which the event-state methods act on. Several
   * when the module draws those features more than once; missing ones are skipped.
   * @protected
   * @ignore
   */
  protected abstract eventStateSources(): (keyof SOURCES_WITH_LAYERS)[];
  /**
   * A named events scope over the given sources, carrying their event states as well.
   * @ignore
   */
  protected userEventsWithStates<T = MapGeoJSONFeature>(sourceNames: (keyof SOURCES_WITH_LAYERS)[], options?: Pick<UserEventsOptions<T, never>, 'mapping' | 'scope'>): UserEventsWithStates<T>;
  /**
   * Puts an event state on one of the shown features, as a user interaction would.
   *
   * @remarks
   * The state is what the module's own layers draw (place pins and entry points, route outlines,
   * geometries, details-module incidents, area-analytics cells), what layers of yours read with
   * `['get', 'eventState']`, and what {@link getEventStates} returns. It lasts as long as the shown
   * feature does, through {@link setVisible}, style and configuration changes, but not a new
   * `show`, a `clear` or a `setStyle` with `resetState`.
   *
   * @example
   * ```typescript
   * // Select a feature from a list, as a click would
   * module.setEventState({ id: feature.properties.id, state: 'click' });
   *
   * // Hover a second one without taking the hover off the first
   * module.setEventState({ index: 2, state: 'hover', mode: 'add' });
   * ```
   */
  setEventState(options: SetEventStateOptions): void;
  /**
   * Takes the event state off one of the shown features.
   *
   * @example
   * ```typescript
   * module.clearEventState({ id: feature.properties.id });
   * ```
   */
  clearEventState(options: ClearEventStateOptions): void;
  /**
   * Takes the given event states, or all of them, off the shown features.
   *
   * @example
   * ```typescript
   * module.clearEventStates(); // every state
   * module.clearEventStates({ states: ['hover'] }); // hovers only, selections stay
   * ```
   */
  clearEventStates(options?: ClearEventStatesOptions): void;
  /**
   * Returns the ids of the shown features that have an event state, by state.
   *
   * @remarks
   * The read side of {@link setEventState} and {@link clearEventStates}, reflecting those and
   * the states user interactions put. The ids are those `getShown()` and the event handlers hand
   * back, so each can go straight back into {@link setEventState}.
   *
   * @example
   * ```typescript
   * // Keep a list in sync with the clicked feature
   * const { click: [clickedID] = [] } = module.getEventStates();
   *
   * // Is this feature hovered?
   * const hovered = module.getEventStates().hover?.includes(feature.properties.id) ?? false;
   * ```
   */
  getEventStates(): EventStateIds;
  /**
   * Swaps the layers of one of this module's sources for `newSpecs`, then re-files this module's
   * event handlers over the layers it now has. See {@link AbstractEventProxy.updateIfRegistered}.
   * @protected
   * @ignore
   */
  protected replaceSourceLayers(newSpecs: ToBeAddedLayerSpecWithoutSource[], oldSpecs: ToBeAddedLayerSpecWithoutSource[], source: GeoJSONSourceWithLayers): void;
}
