export declare const sectionSupportsKnob: <KNOB extends SectionKnobName>(type: DrawnSectionType, knobName: KNOB) => type is SectionTypeWithKnob<KNOB>;
/**
 * Whether the given type draws itself when `sections` says nothing about it.
 *
 * @remarks
 * A panel of section controls needs this answer to show which switches start on. The map can't
 * answer it. A type draws no layer for a route carrying none of its sections, so an absent layer
 * reads the same as a type switched off.
 *
 * @example
 * ```typescript
 * const [drawn, optIn] = partition(drawnSectionTypes, sectionDrawsByDefault);
 * ```
 *
 * @group Routing
 */
export declare const sectionDrawsByDefault: (type: DrawnSectionType) => boolean;
/**
 * A generated type whose presentation is a road sign carrying the section's own value.
 *
 * @remarks
 * Derived from the knob catalogue, so offering `sign` and being drawn as one are the same fact.
 * @ignore
 */
type SignPostingSectionType = { [T in GeneratedSectionType]: 'sign' extends SectionKnobOf<T> ? T : never; }[GeneratedSectionType];
/**
 * A generated type whose presentation is a band along the stretch it covers.
 * @ignore
 */
type BandedSectionType = Exclude<GeneratedSectionType, SignPostingSectionType>;
/**
 * The key the given section type's source, events scope and `getShown()` entry are filed under.
 *
 * @example
 * ```typescript
 * routing.events[sectionSourceKey('lowEmissionZone')].on('click', (section) => { … });
 * const tunnels = routing.getShown()[sectionSourceKey('tunnel')];
 * ```
 *
 * @group Routing
 */
export declare const sectionSourceKey: <T extends DrawnSectionType>(type: T) => SectionSourceKey<T>;
