//#region src/routing/types/displayRoutes.d.ts
/**
 * The props of a displayed route's visual style.
 *
 * They control whether a route appears selected (highlighted) or deselected (dimmed).
 * `showRoutes` selects the route at `selectedIndex`, the first by default, and only `selectRoute`
 * changes the selection after that.
 *
 * @remarks
 * Style states:
 * - `selected`: Primary route with full color saturation and emphasis
 * - `deselected`: Alternative routes shown dimmed/grayed out
 *
 * @example
 * ```typescript
 * // Main selected route
 * const selectedStyle: RouteStateProps = {
 *   routeState: 'selected'
 * };
 *
 * // Alternative route
 * const alternativeStyle: RouteStateProps = {
 *   routeState: 'deselected'
 * };
 * ```
 *
 * @group Routing
 */
type RouteStateProps = {
  /**
   * The route's visual state.
   *
   * @remarks
   * It sets how the route renders on the map:
   * - `selected`: Full color, more prominent (typically the chosen route)
   * - `deselected`: Greyed out, less prominent (alternative routes)
   */
  routeState: 'selected' | 'deselected';
};
/**
 * Route properties with styling and index information.
 *
 * They tie route data to its position in a multi-route result and to its visual state.
 *
 * @remarks
 * The routing module uses them internally to track and style multiple routes.
 * `routeIndex` is the route's position among the routes `showRoutes` was given.
 *
 * @example
 * ```typescript
 * const routeProps: DisplayRouteRelatedProps = {
 *   id: 'route-0-section-3',
 *   routeState: 'selected',
 *   routeIndex: 0  // First route shown
 * };
 * ```
 *
 * @group Routing
 */
type DisplayRouteRelatedProps = RouteStateProps & {
  /**
   * The object's unique identifier, so that MapLibre can display it.
   *
   * @remarks
   * MapLibre is expected to promote this id to the main feature id through the `promoteId` property.
   */
  id: string;
  /**
   * The zero-based position of this route among the routes shown, the index `selectRoute` takes.
   *
   * @remarks
   * It identifies the route this data belongs to when you display multiple alternative routes.
   */
  routeIndex: number;
};
/**
 * Display-ready properties for a route summary bubble.
 *
 * They hold pre-formatted strings to display route information in UI elements
 * such as summary cards, tooltips or info bubbles.
 *
 * @remarks
 * Use cases:
 * - Route comparison cards
 * - Summary bubbles on the map
 * - Route selection UI
 * - Mobile route panels
 *
 * The SDK handles all formatting, units and duration format included, from
 * the configured display settings.
 *
 * @example
 * ```typescript
 * const summary: DisplayRouteSummaryProps = {
 *   id: 'route-0-summary',
 *   routeIndex: 0,
 *   routeState: 'selected',
 *   formattedDistance: '15 km',
 *   formattedDuration: '22 min',
 *   formattedTraffic: '5 min',
 *   magnitudeOfDelay: 'moderate'
 * };
 * ```
 *
 * @group Routing
 */
type DisplayRouteSummaryProps = DisplayRouteRelatedProps & {
  /**
   * The route's distance, formatted in the chosen units.
   *
   * @remarks
   * The SDK formats it from the display units configuration:
   * - Metric: "15 km", "2.9 km" or "500 m"
   * - Imperial (US): "9½ mi" or "600 ft"
   *
   * @example
   * ```typescript
   * formattedDistance: '15 km'
   * formattedDistance: '9½ mi'
   * ```
   */
  formattedDistance?: string;
  /**
   * The route's formatted duration.
   *
   * @remarks
   * Human-readable travel time with appropriate units:
   * - Under half a minute: "< 1 min"
   * - Short: "15 min"
   * - Medium: "1 hr 30 min"
   * - Long: "2 hr 15 min"
   *
   * It accounts for traffic if traffic data is enabled.
   *
   * @example
   * ```typescript
   * formattedDuration: '22 min'
   * formattedDuration: '1 hr 45 min'
   * ```
   */
  formattedDuration?: string;
  /**
   * The route's formatted traffic delay.
   *
   * @remarks
   * It is the summary's `trafficDelayInSeconds`, the delay of the traffic events along the route.
   * It is absent when that delay rounds to under a minute or the routing service did not send it.
   *
   * @example
   * ```typescript
   * formattedTraffic: '5 min'
   * formattedTraffic: '1 hr 15 min'
   * formattedTraffic: undefined  // No delay
   * ```
   */
  formattedTraffic?: string;
  /**
   * The route's overall delay magnitude: the worst `minor`, `moderate` or `major` of its traffic
   * sections.
   *
   * @remarks
   * Absent when the route has no traffic section of a known magnitude, or carries no traffic
   * sections at all. Use it to colour-code delays or show visual indicators in a UI.
   *
   * @example
   * ```typescript
   * magnitudeOfDelay: 'moderate'
   * ```
   */
  magnitudeOfDelay?: DelayMagnitude;
  /**
   * How much longer or shorter the route takes than the selected one, formatted, such as
   * `+6 min` or `-3 min`.
   *
   * @remarks
   * Absent on the selected route, and where both durations round to the same minute. It is the
   * difference of the rounded durations, so it matches the durations the bubbles show.
   */
  formattedDurationDifference?: string;
  /**
   * What a {@link SummaryBubbleLabelConfig.title} function returned for this route, which the
   * bubble writes in place of its fields.
   */
  title?: string;
} & SupportsEvents;
/**
 * The display props of route lines.
 *
 * They combine complete route information with styling and event handling, to render
 * the actual route geometry on the map.
 *
 * @remarks
 * This type extends the base route properties with the display information that
 * rendering and interaction need.
 *
 * @example
 * ```typescript
 * const displayRoute: DisplayRouteProps = {
 *   ...routeData,
 *   routeState: 'selected',
 *   eventState: 'hover'
 * };
 * ```
 *
 * @group Routing
 */
type DisplayRouteProps = RouteProps & RouteStateProps & SupportsEvents;
/**
 * A GeoJSON point feature with display-ready route summary props.
 *
 * It represents one route summary bubble on the map, placed on the route's longest distinct
 * section, as {@link SummaryBubblesConfig} describes.
 *
 * @remarks
 * Use cases:
 * - Summary bubbles along the route
 * - Interactive route details
 *
 * @example
 * ```typescript
 * const summaryFeature: DisplayRouteSummary = {
 *   type: 'Feature',
 *   geometry: {
 *     type: 'Point',
 *     coordinates: [4.9, 52.3]
 *   },
 *   properties: {
 *     id: 'route-0-summary',
 *     routeIndex: 0,
 *     routeState: 'selected',
 *     formattedDistance: '15 km',
 *     formattedDuration: '22 min'
 *   }
 * };
 * ```
 *
 * @group Routing
 */
type DisplayRouteSummary = Feature<Point, DisplayRouteSummaryProps>;
/**
 * A GeoJSON feature collection of points with display-ready route summary props.
 *
 * It holds the summary bubbles of all routes, one per route that has coordinates, for
 * displaying route alternatives with summary information.
 *
 * @example
 * ```typescript
 * const summaries: DisplayRouteSummaries = {
 *   type: 'FeatureCollection',
 *   features: [
 *     {
 *       type: 'Feature',
 *       geometry: { type: 'Point', coordinates: [4.9, 52.3] },
 *       properties: {
 *         id: 'route-0-summary',
 *         routeIndex: 0,
 *         routeState: 'selected',
 *         formattedDistance: '15 km',
 *         formattedDuration: '22 min'
 *       }
 *     },
 *     {
 *       type: 'Feature',
 *       geometry: { type: 'Point', coordinates: [4.85, 52.35] },
 *       properties: {
 *         id: 'route-1-summary',
 *         routeIndex: 1,
 *         routeState: 'deselected',
 *         formattedDistance: '19 km',
 *         formattedDuration: '25 min'
 *       }
 *     }
 *   ]
 * };
 * ```
 *
 * @group Routing
 */
type DisplayRouteSummaries = FeatureCollection<Point, DisplayRouteSummaryProps>;
/**
 * Display-ready props of one border crossing.
 *
 * @group Routing
 */
type DisplayCountryCrossingProps = DisplayRouteRelatedProps & {
  /** ISO 3166-1 alpha-2 code of the country the route leaves. */
  fromCountryCode: string;
  /** ISO 3166-1 alpha-2 code of the country the route enters. */
  toCountryCode: string;
  /** The label its bubble stretches around, such as `'ES → FR'`. */
  label: string;
  /**
   * `startPointIndex` of the `country` section the route leaves, which identifies that section
   * on {@link RouteProps.sections} even when the route enters the same country twice.
   */
  fromSectionStartPointIndex: number;
  /** `startPointIndex` of the `country` section the route enters. */
  toSectionStartPointIndex: number;
};
/**
 * GeoJSON feature of one border crossing, placed where the route enters the second country.
 *
 * @group Routing
 */
type DisplayCountryCrossing = Feature<Point, DisplayCountryCrossingProps>;
/**
 * A border crossing as an event hands it over, which is the drawn feature plus the two `country`
 * sections it joins.
 *
 * @remarks
 * The sections are looked up on the route the crossing belongs to, so they are the same objects
 * `route.properties.sections.country` holds rather than copies. They are absent only when the route
 * that carried them is no longer shown.
 *
 * @group Routing
 */
type CountryCrossingFeature = Feature<Point, DisplayCountryCrossingProps & {
  /** The `country` section the route leaves. */
  fromSection?: CountrySectionProps;
  /** The `country` section the route enters. */
  toSection?: CountrySectionProps;
}>;
/**
 * GeoJSON feature collection of the border crossings along the shown routes.
 *
 * @group Routing
 */
type DisplayCountryCrossings = FeatureCollection<Point, DisplayCountryCrossingProps>;
//#endregion
//#region src/routing/types/waypointDisplayProps.d.ts
/**
 * The {@link WaypointDisplayProps.indexType} of the route's origin.
 *
 * @group Routing
 */
export declare const START_INDEX = "start";
/**
 * The {@link WaypointDisplayProps.indexType} of a stop between the origin and the destination.
 *
 * @group Routing
 */
export declare const MIDDLE_INDEX = "middle";
/**
 * The {@link WaypointDisplayProps.indexType} of the route's destination.
 *
 * @group Routing
 */
export declare const FINISH_INDEX = "finish";
/**
 * Where a waypoint sits on its route: the origin, a stop or the destination.
 *
 * @group Routing
 */
type WaypointIndexType = typeof START_INDEX | typeof MIDDLE_INDEX | typeof FINISH_INDEX;
/**
 * Display properties for a waypoint marker on the map.
 *
 * They extend location display properties with waypoint-specific information,
 * including route position and stop numbering.
 *
 * @remarks
 * Waypoints display differently by their position:
 * - Start: Origin marker (often "A" or green pin)
 * - Middle: Numbered stop markers (1, 2, 3, etc.)
 * - Finish: Destination marker (often "B" or red pin)
 *
 * @example
 * ```typescript
 * // Start waypoint
 * const start: WaypointDisplayProps = {
 *   id: 'waypoint-0',
 *   iconID: 'waypointStart-0',
 *   index: 0,
 *   indexType: 'start',
 *   title: 'Amsterdam Central Station'
 * };
 *
 * // Intermediate stop
 * const stop: WaypointDisplayProps = {
 *   id: 'waypoint-1',
 *   iconID: 'waypointStop-0',
 *   index: 1,
 *   indexType: 'middle',
 *   stopDisplayIndex: 1,
 *   title: 'Schiphol Airport'
 * };
 *
 * // Destination
 * const finish: WaypointDisplayProps = {
 *   id: 'waypoint-2',
 *   iconID: 'waypointFinish-0',
 *   index: 2,
 *   indexType: 'finish',
 *   title: 'Rotterdam Central Station'
 * };
 * ```
 *
 * @group Routing
 */
type WaypointDisplayProps = Omit<PlaceDisplayProps, 'id'> & {
  /**
   * The waypoint's id: the one you gave it, a string or a number, otherwise a generated string.
   *
   * @remarks
   * It identifies the waypoint in event handlers, {@link UserEventsWithStates.setEventState} and
   * {@link UserEventsWithStates.getEventStates}, which return it as given.
   */
  id: string | number;
  /**
   * The waypoint's index among the other waypoints.
   *
   * @remarks
   * It is zero-based, over the complete waypoints array including start, all stops
   * and finish.
   *
   * @example
   * ```typescript
   * index: 0  // First waypoint (start)
   * index: 1  // Second waypoint (first stop or finish)
   * index: 2  // Third waypoint
   * ```
   */
  index: number;
  /**
   * The type of the index, which describes where the waypoint sits in the list of waypoints.
   *
   * @remarks
   * It sets the waypoint's role and look:
   * - `start`: Origin point
   * - `middle`: Intermediate stop
   * - `finish`: Final destination
   *
   * It affects icon selection and labelling.
   */
  indexType: WaypointIndexType;
  /**
   * The stop index to display.
   *
   * @remarks
   * Stops are the waypoints between origin and destination, numbered from 1. It is
   * present only for middle waypoints.
   *
   * Display behaviour:
   * - Start waypoint: undefined
   * - First stop: 1
   * - Second stop: 2
   * - Finish waypoint: undefined
   *
   * Use it to display stop numbers, such as "Stop 1" or "Stop 2", in the UI.
   *
   * @example
   * ```typescript
   * stopDisplayIndex: 1  // First intermediate stop
   * stopDisplayIndex: 2  // Second intermediate stop
   * stopDisplayIndex: undefined  // Start or finish waypoint
   * ```
   */
  stopDisplayIndex?: number;
  /**
   * The mark the stop's pin draws inside it, under {@link WaypointsConfig.stopNumbering}, such as
   * `'2'` or `'B'` for the second stop.
   *
   * @remarks
   * Absent on the origin and destination, under `'none'`, and on a stop drawn with a `middle.image`
   * or a mapped icon, none of which carries a mark.
   */
  stopDisplayLabel?: string;
  /**
   * How long the route waits at this waypoint, formatted for display.
   *
   * @remarks
   * Taken from {@link WaypointProps.pauseDurationSeconds} and rendered on the stop's label by
   * default (e.g. `30 min`). Absent when the waypoint carries no wait.
   *
   * @example
   * ```typescript
   * stopDuration: '30 min'
   * ```
   */
  stopDuration?: string;
};
/**
 * A waypoint as {@link RoutingModule} draws it and as `waypoints.icon.mapping` and
 * `waypoints.label.title` receive it, with the properties it was given (a place's, when it was a
 * search result) and its {@link WaypointDisplayProps}.
 *
 * @group Routing
 */
type DisplayWaypoint = Waypoint<WaypointDisplayProps & Partial<CommonPlaceProps>>;
//#endregion
//#region src/routing/types/routeModuleConfig.d.ts
/**
 * The MapLibre layer id of a generated section's line layer.
 *
 * @remarks
 * Derived from the section type, so `motorway` is drawn by `routeSectionMotorwayLine`.
 * @group Routing
 */
type SectionLineLayerName<T extends GeneratedSectionType = GeneratedSectionType> = `routeSection${Capitalize<T>}Line`;
/**
 * The MapLibre layer id of a section's icon layer.
 *
 * @remarks
 * Added to a generated section as soon as `sections.<type>.icon` asks for one, so `motorway` draws
 * its icon through `routeSectionMotorwaySymbol`.
 * @group Routing
 */
type SectionSymbolLayerName<T extends GeneratedSectionType = GeneratedSectionType> = `routeSection${Capitalize<T>}Symbol`;
/**
 * The MapLibre layer id drawing the signs of one generated section type.
 *
 * @remarks
 * Present for the types that post their own value on a sign, so `speedLimit` draws its signs
 * through `routeSectionSpeedLimitSign`.
 * @group Routing
 */
type SectionSignLayerName<T extends GeneratedSectionType = GeneratedSectionType> = `routeSection${Capitalize<T>}Sign`;
/**
 * The MapLibre layer id of the kerb stripes a generated section draws over its tight sections'
 * line.
 *
 * @remarks
 * Present for the types that take a `kerb`, so `curve` draws its kerb through
 * `routeSectionCurveKerb`.
 * @group Routing
 */
type SectionKerbLayerName<T extends GeneratedSectionType = GeneratedSectionType> = `routeSection${Capitalize<T>}Kerb`;
/**
 * Detailed configuration of the route layers' look on the map, in the MapLibre specification.
 *
 * @remarks
 * It gives fine-grained control over every route layer, including main route lines,
 * waypoints, route sections (ferry, tunnel, toll roads and others), turn-by-turn guidance
 * instructions and route summaries.
 *
 * All fields are optional. A field you leave out uses the default styling.
 *
 * @group Routing
 */
type RouteLayersConfig = {
  /**
   * Main route line layer specifications.
   *
   * @remarks
   * They style the primary route path on the map, and can include both line and symbol layers.
   */
  mainLines?: {
    /**
     * Styling for the primary, selected route line.
     *
     * @remarks
     * It sets the active route line's colour, width, dash pattern and more.
     */
    routeLine?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
    /**
     * Styling for the outline (stroke) around the primary route line.
     *
     * @remarks
     * It typically sets the route apart from the map background.
     */
    routeOutline?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
    /**
     * Styling for the deselected (inactive) route line.
     *
     * @remarks
     * It applies when multiple routes are shown and some are visually de-emphasized.
     */
    routeDeselectedLine?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
    /**
     * Styling for the outline around the deselected route line.
     *
     * @remarks
     * It matches `routeDeselectedLine` and adds an outer stroke for visibility.
     */
    routeDeselectedOutline?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
    /**
     * Symbol layer that draws directional arrows along the main route.
     *
     * @remarks
     * They help show the travel direction on routes with complex geometry.
     */
    routeLineArrows?: Partial<ToBeAddedLayerSpecTemplate<SymbolLayerSpecification>>;
  } & HasAdditionalLayersConfig;
  /**
   * Waypoint layer specifications.
   *
   * @remarks
   * They style the waypoint icons (origin, destination and intermediate stops) and their labels
   * along the route.
   */
  waypoints?: {
    /**
     * Symbol layer for waypoint icons (origin, destination, stops).
     *
     * @remarks
     * Use it to customise the waypoints' icons, sizes and placement.
     */
    routeWaypointSymbol?: Partial<ToBeAddedLayerSpecTemplate<SymbolLayerSpecification>>;
    /**
     * Symbol layer for waypoint labels displayed next to waypoint icons.
     *
     * @remarks
     * It sets the labels' text, font and offset.
     */
    routeWaypointLabel?: Partial<ToBeAddedLayerSpecTemplate<SymbolLayerSpecification>>;
  } & HasAdditionalLayersConfig;
  /**
   * Layer specifications for route sections, keyed by section type.
   *
   * @remarks
   * Each section is a subset of the route path. Every type the module draws has an entry here,
   * in the same vocabulary as the semantic `sections` config, one tier down. Use it when the
   * knobs on `sections` are not enough and you need full MapLibre control over the layers a
   * section is drawn with.
   *
   * The generated types that band the route carry a line layer, and an icon layer once
   * `sections.<type>.icon` asks for one; `curve` adds the layer of the kerb it stripes its tight
   * curves with, and `speedLimit` carries only its sign layer. The remaining five draw themselves
   * with the hand-written layers documented below.
   */
  sections?: { [T in Exclude<GeneratedSectionType, SectionTypeWithKnob<'sign'>>]?: { [K in SectionLineLayerName<T>]?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>; } & { [K in SectionSymbolLayerName<T>]?: Partial<ToBeAddedLayerSpecTemplate<SymbolLayerSpecification>>; } & { [K in SectionKerbLayerName<Extract<T, SectionTypeWithKnob<'kerb'>>>]?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>; } & HasAdditionalLayersConfig; } & { [T in Extract<GeneratedSectionType, SectionTypeWithKnob<'sign'>>]?: { [K in SectionSignLayerName<T>]?: Partial<ToBeAddedLayerSpecTemplate<SymbolLayerSpecification>>; } & HasAdditionalLayersConfig; } & {
    /**
     * Ferry crossing section layers.
     *
     * @remarks
     * They style the route's ferry stretches.
     */
    ferry?: {
      /**
       * Symbol layer marking where each ferry section starts, at its boarding terminal.
       */
      routeFerrySymbol?: Partial<ToBeAddedLayerSpecTemplate<SymbolLayerSpecification>>;
      /**
       * Line layer of the ferry crossing path.
       *
       * @remarks
       * By default a solid light-blue line that stands in for the route line along the crossing.
       */
      routeFerryLine?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
    } & HasAdditionalLayersConfig;
    /**
     * Traffic incident section layers.
     *
     * @remarks
     * They highlight route segments affected by traffic incidents or disruptions.
     */
    traffic?: {
      /**
       * Symbol layer marking where a jam on the route starts.
       *
       * @remarks
       * It shows jams with delays.
       */
      routeIncidentJamSymbol?: Partial<ToBeAddedLayerSpecTemplate<SymbolLayerSpecification>>;
      /**
       * Symbol layer marking the cause where an incident on the route starts.
       *
       * @remarks
       * It can show icons for accidents, roadworks, weather or other incidents.
       */
      routeIncidentCauseSymbol?: Partial<ToBeAddedLayerSpecTemplate<SymbolLayerSpecification>>;
      /**
       * Line layer of each traffic section, coloured by its `magnitudeOfDelay`.
       *
       * @remarks
       * Override its `line-color` to recolour the delays.
       */
      routeIncidentBackgroundLine?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
      /**
       * Line layer dashing the traffic sections whose `magnitudeOfDelay` is `unknown` or
       * `indefinite`, over the line above.
       */
      routeIncidentDashedLine?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
    } & HasAdditionalLayersConfig;
    /**
     * Layers for the `tollRoad` section type.
     *
     * @remarks
     * Marks the stretches of the route that cost money to drive, by any charging scheme:
     * per-use tolls, motorways that need a vignette, and urban road-charge zones.
     */
    tollRoad?: {
      /**
       * Symbol layer marking the charged stretches with an icon.
       *
       * @remarks
       * By default, it draws the toll-plaza icon, the closest the base-map sprite offers to a
       * generic road-charge icon. To tell the schemes apart yourself, override it.
       */
      routeTollRoadSymbol?: Partial<ToBeAddedLayerSpecTemplate<SymbolLayerSpecification>>;
      /**
       * Line layer outlining the charged stretches.
       *
       * @remarks
       * It is typically styled to set charged stretches apart from regular roads.
       */
      routeTollRoadOutline?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
    } & HasAdditionalLayersConfig;
    /**
     * Tunnel section layers.
     *
     * @remarks
     * They highlight route segments that pass through tunnels.
     */
    tunnel?: {
      /**
       * Line layer of the tunnel segments along the route.
       *
       * @remarks
       * It often has a distinct colour or transparency to mark tunnels.
       */
      routeTunnelLine?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
      /**
       * Symbol layer posting a tunnel sign where each tunnel starts, from zoom 10.
       *
       * @remarks
       * It is drawn above the map's labels and under the route's other icons, so it gives way
       * to every route icon but the ones generated section types ask for.
       */
      routeTunnelSymbol?: Partial<ToBeAddedLayerSpecTemplate<SymbolLayerSpecification>>;
    } & HasAdditionalLayersConfig;
    /**
     * Vehicle-restricted section layers.
     *
     * @remarks
     * Stretches the requested vehicle is not permitted to use, which the route still takes.
     */
    vehicleRestricted?: {
      /**
       * Background line layer for vehicle-restricted segments.
       *
       * @remarks
       * It gives a base style that makes restricted segments visible.
       */
      routeVehicleRestrictedBackgroundLine?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
      /**
       * Foreground line layer for vehicle-restricted segments.
       *
       * @remarks
       * It sits on top of the background to emphasise the restricted area.
       */
      routeVehicleRestrictedForegroundLine?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
      /**
       * Symbol layer posting a "closed to vehicles" sign, an empty red ring, where each restricted
       * stretch starts, from zoom 10.
       *
       * @remarks
       * It is drawn just under the traffic icons and above the ferry icons, the map's labels
       * and, at their default `sign.priority`, the speed limit signs, so it wins the space over those.
       */
      routeVehicleRestrictedSymbol?: Partial<ToBeAddedLayerSpecTemplate<SymbolLayerSpecification>>;
    } & HasAdditionalLayersConfig;
  };
  /**
   * Turn-by-turn instruction line layers.
   *
   * @remarks
   * They draw the individual manoeuvre segments of the guidance instructions.
   */
  instructionLines?: {
    /**
     * Line layer for the outline around instruction segments.
     *
     * @remarks
     * It keeps instruction segments readable over complex map backgrounds.
     */
    routeInstructionOutline?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
    /**
     * Line layer for the instruction segment itself.
     *
     * @remarks
     * It follows the precise geometry of the manoeuvre the instruction is shown for.
     */
    routeInstructionLine?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
  } & HasAdditionalLayersConfig;
  /**
   * Turn-by-turn instruction arrow layers.
   *
   * @remarks
   * Arrows that show the direction of travel for each manoeuvre.
   */
  instructionArrows?: {
    /**
     * Symbol layer for the direction arrows placed along manoeuvre segments.
     *
     * @remarks
     * It sets the arrow icon, rotation and placement relative to the instruction geometry.
     */
    routeInstructionArrowSymbol?: Partial<ToBeAddedLayerSpecTemplate<SymbolLayerSpecification>>;
  } & HasAdditionalLayersConfig;
  /**
   * Route summary bubble layers.
   *
   * @remarks
   * They show summary information, such as total distance and estimated time.
   */
  summaryBubbles?: {
    /**
     * Symbol layer for the route summary bubble icon and label.
     *
     * @remarks
     * Use this layer to style the small summary popups or badges shown on the route.
     */
    routeSummaryBubbleSymbol?: Partial<ToBeAddedLayerSpecTemplate<SymbolLayerSpecification>>;
  } & HasAdditionalLayersConfig;
  /**
   * Border crossing layers.
   *
   * @remarks
   * Anything {@link CountryCrossingConfig} cannot express about the bubble or its label.
   */
  countryCrossings?: {
    /**
     * Symbol layer writing each crossing's label in its bubble.
     */
    routeCountryCrossing?: Partial<ToBeAddedLayerSpecTemplate<SymbolLayerSpecification>>;
  } & HasAdditionalLayersConfig;
  /**
   * Layers of the sections {@link RoutingModule.setSectionFocus} marks.
   *
   * @remarks
   * Anything {@link RouteHighlightConfig} `section` cannot express about the ring.
   */
  sectionFocus?: {
    /**
     * Line layer ringing each focused section of the selected route, drawn with a
     * `line-gap-width` as wide as the widest line along the route, so the route and its
     * sections show through. It sits under the route's own lines, which cover it where the
     * road doubles back and where focused sections meet.
     */
    routeSectionFocusOutline?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
    /**
     * Line layer ringing each focused section of a deselected route, under that route's own
     * lines and so under the selected route where they cross.
     */
    routeDeselectedSectionFocusOutline?: Partial<ToBeAddedLayerSpecTemplate<LineLayerSpecification>>;
  } & HasAdditionalLayersConfig;
};
/**
 * The waypoint pins, one per role (origin, stops, destination), each in the SDK's pin or an image
 * of your own, plus an optional icon per waypoint picked from its data.
 *
 * @remarks
 * A pin's style is laid over, in order: the route colour as its fill, `style`, and the role's own
 * `style`. A role's `image` replaces its pin, and `mapping` replaces the role's icon for the
 * waypoints it returns an id or category for.
 *
 * @example
 * ```typescript
 * const icon: WaypointIconConfig = {
 *   style: { outlineColor: '#FFFFFF' },
 *   start: { style: { fillColor: '#1B7A43' } },
 *   finish: { image: { image: '/flag.svg', pixelRatio: 2 } },
 *   // Stops that are charging stations look like the map's charging stations:
 *   mapping: { to: 'poiCategory', fn: (waypoint) => waypoint.properties.poi?.categories?.[0] },
 * };
 * ```
 *
 * @group Routing
 */
type WaypointIconConfig = {
  /**
   * Style of all three pins, under each role's own `style`.
   */
  style?: SVGIconStyleOptions;
  /**
   * The origin's pin.
   */
  start?: PinIconConfig;
  /**
   * The pin of every stop between origin and destination.
   */
  middle?: PinIconConfig;
  /**
   * The destination's pin.
   */
  finish?: PinIconConfig;
  /**
   * Images for `mapping` to pick by id.
   *
   * @remarks
   * Each is added under its own `id`, so `mapping` returns that id. An entry's `offsetX`/`offsetY`
   * shift that icon from the waypoint's position, and apply only to an entry with an `image`. An
   * entry naming a sprite icon by `id` alone ignores them.
   */
  customIcons?: CustomImage[];
  /**
   * The icon of each waypoint, picked from its data.
   *
   * @remarks
   * `fn` receives the waypoint as drawn, with its own properties plus its `indexType` role and the
   * role's `iconID`. If it returns `undefined`, the role's pin stays. A `poiCategory` draws the
   * pin {@link PlacesModule} draws for that category. A mapped icon carries no
   * {@link WaypointStopNumbering | stop mark}.
   */
  mapping?: IconMapping<DisplayWaypoint>;
};
/**
 * How the stops between origin and destination are marked inside their pin.
 *
 * @remarks
 * - `numbers`: 1, 2, 3…
 * - `letters`: A, B, C…, then AA, AB… after Z.
 * - `none`: an empty pin.
 *
 * Only the SDK's stop pin carries the mark. A `middle.image` or a mapped icon draws without one.
 *
 * @group Routing
 */
type WaypointStopNumbering = 'numbers' | 'letters' | 'none';
/**
 * The waypoint labels' visibility, text and look.
 *
 * @remarks
 * Unset colours follow the map's light/dark theme, as the labels of places and geometries do. A
 * light map gets `'#333333'` text on a `'#FFFFFF'` halo, and a dark one the two swapped. By default
 * a label writes the waypoint's POI name or address, and under it how long the route waits there.
 *
 * @group Routing
 */
type WaypointLabelConfig = FeatureLabelConfig<DisplayWaypoint> & {
  /**
   * Whether the labels show.
   *
   * @defaultValue `true`
   */
  visible?: boolean;
};
/**
 * The highlight of a hovered or clicked waypoint, whose pin and stop mark grow.
 *
 * @remarks
 * The waypoints draw their event states once a handler covers them, or
 * `routing.events.waypoints.setEventState` puts one.
 *
 * @group Routing
 */
type WaypointHighlightConfig = {
  /**
   * The multiplier on a hovered or clicked waypoint's pin size. At `1`, it draws as any other.
   *
   * @remarks
   * Clamped to 1 to 1.5, its `range` in {@link routingKnobCatalogue}.
   *
   * @defaultValue `1.2`
   */
  sizeFactor?: number;
};
/**
 * How the module draws the waypoints {@link RoutingModule.showWaypoints} is given.
 *
 * @remarks
 * Each setting reaches the waypoints already shown.
 *
 * @group Routing
 */
type WaypointsConfig = {
  /**
   * Size preset of the waypoint pins and their stop marks.
   *
   * @defaultValue `"m"`
   */
  sizePreset?: RouteWaypointSize;
  /**
   * Multiplier over the {@link sizePreset}, where `1` leaves it unchanged. The two compose.
   *
   * @remarks
   * Clamped to 0.5 to 2, its `range` in {@link routingKnobCatalogue}.
   *
   * @defaultValue `1`
   */
  sizeFactor?: number;
  /**
   * The waypoint pins, per role, and an optional icon per waypoint picked from its data.
   */
  icon?: WaypointIconConfig;
  /**
   * How the stops between origin and destination are marked inside their pin.
   *
   * @defaultValue `"numbers"`
   */
  stopNumbering?: WaypointStopNumbering;
  /**
   * The waypoint labels' visibility, text and look.
   */
  label?: WaypointLabelConfig;
  /**
   * How a hovered or clicked waypoint is drawn.
   */
  highlight?: WaypointHighlightConfig;
  /**
   * How the module uses entry points when it displays waypoints on the map.
   *
   * @remarks
   * An entry point is the actual navigable entrance to a location,
   * which may differ from its geometric centre coordinates.
   *
   * Available options:
   * - `main-when-available` - Uses the coordinates of the entry point {@link GetPositionEntryPointOption} picks,
   *   otherwise the waypoint coordinates
   * - `ignore` - Always uses the original waypoint coordinates
   *
   * @defaultValue `"ignore"`
   */
  entryPoints?: GetPositionEntryPointOption;
};
/**
 * Route line thickness preset.
 *
 * @remarks
 * Controls the thickness of the route line, its outline, the section lines and the instruction
 * lines at all zoom levels. Each preset is a zoom profile of its own, tuned so the outline stays a
 * readable rim at every thickness. A `widthFactor` multiplies whichever preset applies.
 *
 * Available options:
 * - `"s"` - Thin line, suitable for dense or cluttered maps
 * - `"m"` - Default medium thickness
 * - `"l"` - Thick line, useful for high emphasis or accessibility
 *
 * @group Routing
 */
type RouteWidth = 's' | 'm' | 'l';
/**
 * Route waypoint icon size preset.
 *
 * @remarks
 * It sets the scale of waypoint pins, and of the stop mark inside them, at all zoom levels.
 * `"s"` is 0.75 × `"m"`, and `"l"` is 1.25 × `"m"`. {@link WaypointsConfig.sizeFactor}
 * multiplies whichever preset applies.
 *
 * Available options:
 * - `"s"` - Small icons
 * - `"m"` - Default medium icons
 * - `"l"` - Large icons
 *
 * @group Routing
 */
type RouteWaypointSize = 's' | 'm' | 'l';
/**
 * Where a section's icon sits on it.
 *
 * - `center`: one icon at the middle of each section.
 * - `along`: icons repeated along the section.
 *
 * @group Routing
 */
type SectionIconPlacement = 'center' | 'along';
/**
 * The icon drawn on a route section.
 *
 * @remarks
 * A symbol layer over the section's own source draws it. The generated section types get one
 * added, and the types that already draw an icon (`ferry`, `tollRoad`, `tunnel` and
 * `vehicleRestricted`) have theirs replaced.
 *
 * @group Routing
 */
type SectionIconConfig = {
  /**
   * The id of an image in the loaded style's sprite, such as `poi-toll_plaza`. An id the sprite does
   * not carry draws nothing.
   */
  image: string;
  /**
   * Where the icon sits on the section.
   *
   * @defaultValue `"center"` on the generated types; the bespoke types that draw an icon keep their own placement.
   */
  placement?: SectionIconPlacement;
  /**
   * Multiplier over the size the type draws its icon at. That is the sprite image's own size on
   * the generated types, and the zoom-ramped size on `ferry`, `tollRoad`, `tunnel` and
   * `vehicleRestricted`. Clamped to 0.25 to 2, its `range` in {@link routingKnobCatalogue}.
   *
   * @defaultValue `1`
   */
  sizeFactor?: number;
};
type SectionKnobs = {
  /**
   * Whether the section is drawn at all.
   *
   * @remarks
   * Each type has its own default, set by one rule. A type draws itself when its stretches are
   * sparse along a route and consequential for the driver. `carTrain`, `ferry`, `lowEmissionZone`,
   * `tollRoad`, `tollVignette`, `traffic`, `tunnel` and `vehicleRestricted` do, until you switch
   * them off here, and so does `speedLimit`, which posts a sign per section rather than banding
   * the route. The rest draw only when you ask. `motorway` and `urban` each run nearly a route's
   * whole length, so a band drawn for them buries the route line.
   */
  visible?: boolean;
  /**
   * Line colour, as any CSS colour string. Each section type has its own default. On a type
   * drawn with more than one line, this sets the principal one, and the rest derive from it.
   * `curve` draws it in full only at a `severity` of 1, and fades it toward the map the gentler
   * the curve is.
   */
  color?: string;
  /**
   * Line opacity, 0 to 1. `ferry`, `tollRoad`, `traffic` and `vehicleRestricted` default to opaque,
   * and the other types to partial opacity so the route line stays readable underneath.
   */
  opacity?: number;
  /**
   * Line width preset. Defaults to the route's own width.
   */
  widthPreset?: RouteWidth;
  /**
   * Multiplier over the section's {@link widthPreset}, and the two compose. It defaults to the
   * route's own `widthFactor`, and is clamped to 0.5 to 2, its `range` in {@link routingKnobCatalogue}.
   *
   * @remarks
   * A `halo` section never draws narrower than 1.26 times the route's outline width, whatever its
   * preset and factor, so it stays a band around the route.
   */
  widthFactor?: number;
  /**
   * Whether the section bands the route (`halo`) or stands in for the route line along its own
   * stretch (`inline`). This decides both where the section's line sits in the layer order and
   * how wide it is drawn. {@link SectionDrawStyle} lists each type's default.
   */
  style?: SectionDrawStyle;
  /**
   * Line pattern. Each type has its own default. A broken line marks a stretch the driver doesn't
   * simply drive along as usual: `carTrain`, `pedestrian`, `tollVignette` and `unpaved` are
   * dashed, `vehicleRestricted` is dotted, and the rest are solid.
   */
  pattern?: LinePattern;
  /**
   * An icon drawn on the section. `ferry`, `tollRoad`, `tunnel` and `vehicleRestricted` draw one
   * where each section starts, which this replaces. None of the generated types draws one by
   * default.
   */
  icon?: SectionIconConfig;
  /**
   * The sign a section posts its own value on, for `speedLimit`, the one type whose information
   * is a number rather than a stretch.
   */
  sign?: SectionSignConfig;
  /**
   * The kerb a section stripes its tight stretches with, for `curve`, the one type with a radius to
   * tell them by.
   */
  kerb?: SectionKerbConfig;
};
/**
 * The kerb a tight curve carries: short stripes over its line, which shows between them.
 *
 * @remarks
 * Only a curve with a radius of 60 m or less carries one, the kind a driver slows right down for,
 * and only from zoom 12, where the curve is drawn large enough to show it.
 *
 * @example
 * ```typescript
 * // Blue curves with yellow kerbs
 * sections: { curve: { visible: true, color: '#0057B8', kerb: { color: '#FFD700' } } }
 * // One plain line
 * sections: { curve: { visible: true, kerb: { visible: false } } }
 * ```
 *
 * @group Routing
 */
type SectionKerbConfig = {
  /**
   * Whether the stripes are drawn.
   *
   * @defaultValue true
   */
  visible?: boolean;
  /**
   * The colour of the stripes, as any CSS colour string.
   *
   * @defaultValue A faint shade of the section's `color`, faded toward white on a light map and
   * toward near-black on a dark one
   */
  color?: string;
};
/**
 * The unit a speed limit sign reads in.
 *
 * @group Routing
 */
type SectionSignUnit = 'km/h' | 'mph';
/**
 * Where a section's signs are posted along the stretch they belong to.
 *
 * @remarks
 * - `atChange` - The default. One sign stands where the value changes and none after it, which is
 *   where the road posts its own. Sections of a sign-posting type tile the route end to end, and no
 *   two consecutive ones carry the same value, so every section boundary is a change.
 * - `along` - The sign repeats down the stretch at a fixed screen spacing, so a reader zoomed into
 *   the middle of a long one still sees the value in force. A stretch too short on screen to fit a
 *   sign draws none.
 *
 * A stretch can run 50 km. So under `atChange`, a reader zoomed in past its start sees no sign
 * until the next change, as on the road itself.
 *
 * @group Routing
 */
type SectionSignPlacement = 'atChange' | 'along';
/**
 * What a section's signs give way to when two symbols want the same spot.
 *
 * @remarks
 * MapLibre resolves symbol collisions from the topmost layer down, so the layer underneath is the
 * one that gives way.
 *
 * - `belowMapLabels` - The signs give way to everything, the base map's own labels included. A sign
 *   never lands on a street or place name, at the cost of showing fewer in a city. That cost is
 *   small under `along` placement, where the dropped sign is posted again further down the stretch.
 * - `belowRouteIcons` - The signs give way to every icon the route draws, section icons included,
 *   since each says something the road cannot. They take precedence over the base map's labels.
 * - `aboveRouteIcons` - The signs give way to nothing, for a map whose subject is the limits.
 *
 * @group Routing
 */
type SectionSignPriority = 'belowMapLabels' | 'belowRouteIcons' | 'aboveRouteIcons';
/**
 * The sign a section type posts its own value on.
 *
 * @remarks
 * `speedLimit` is the one type that takes this, and it draws only signs. It draws no line along the
 * stretch, because a line would mark every stretch that carries a limit without ever saying what
 * the limit is. {@link SectionDisplayConfig.visible} switches the signs
 * themselves.
 *
 * The sign follows the road rather than the reader. Where the route also carries `country`
 * sections, each sign takes the face, the unit and the numeral colour of the country its stretch
 * runs through: the white disc most of Europe posts on, the yellow one Sweden, Finland and Iceland
 * use, the `SPEED LIMIT` plaque of the United States, and Japan's blue numerals. A country with no
 * entry posts the white disc in km/h.
 *
 * Where mph is posted, the number is converted and rounded to the step signs come in. Without
 * `country` sections, the display units decide the face and the unit, and an explicit {@link unit}
 * overrides both.
 *
 * A sign stands where the limit changes, and {@link placement} repeats it down the stretch instead.
 * Signs scale with the zoom, as the ferry and toll-road icons do, a tenth smaller than the tunnel
 * and closed-road signs. {@link minZoom} decides how early they appear at all.
 *
 * @group Routing
 */
type SectionSignConfig = {
  /**
   * Where the signs are posted along the stretch.
   *
   * @defaultValue `'atChange'`, which is where the road posts its own.
   */
  placement?: SectionSignPlacement;
  /**
   * The lowest zoom the signs are drawn at.
   *
   * @defaultValue 12.5, two and a half zooms past the tunnel and closed-road signs. A route posts many more
   * speed limits, and further out they crowd the overview of the route.
   */
  minZoom?: number;
  /**
   * What a sign gives way to when another symbol wants the same spot.
   *
   * @remarks
   * {@link RoutingModuleConfig.beforeLayerConfig} decides where the route icons sit. This
   * places the signs relative to them and to the map's labels.
   *
   * @defaultValue follows {@link placement}: `'belowRouteIcons'` under `atChange`, where the sign
   * is the only one posting that change; `'belowMapLabels'` under `along`, where the next repeat
   * posts it again.
   */
  priority?: SectionSignPriority;
  /**
   * The unit every sign reads in, whatever the road posts.
   *
   * @remarks
   * If you leave it out, each sign follows its own country, or the display units where the route
   * carries no `country` sections.
   */
  unit?: SectionSignUnit;
};
/**
 * Appearance of the border crossings along a route.
 *
 * @remarks
 * A crossing is the seam between two consecutive `country` sections, so it is a point rather than a
 * stretch. It takes knobs of its own instead of a place in the section catalogue. Each is a label
 * naming both countries by their ISO 3166-1 alpha-2 codes in the direction of travel, such as
 * `'ES → FR'`, in a bubble standing above the route as the route summaries do.
 *
 * The bubble takes the selected route summary's default colours unless {@link color} or `label.color`
 * says otherwise, so it follows the map's theme and colour knobs without being reconfigured. A
 * `summaryBubbles` colour of yours does not reach it.
 *
 * A crossing gives way to the waypoint pins, the summaries and any symbol drawn above it: where one
 * covers it, it hides.
 *
 * @example
 * ```typescript
 * const routes = await calculateRoute({ locations, sectionTypes: ['country'] });
 * await routing.showRoutes(routes);
 * ```
 *
 * @group Routing
 */
type CountryCrossingConfig = {
  /**
   * Whether the crossings are drawn.
   *
   * @defaultValue `true`
   */
  visible?: boolean;
  /**
   * The lowest zoom a crossing is drawn at.
   *
   * @defaultValue 4, low enough for a continental route to show its borders while framed whole.
   */
  minZoom?: number;
  /**
   * The bubble colour behind the label.
   *
   * @defaultValue the selected route summary's colour, {@link SummaryBubblesConfig.color}'s default:
   * the map's `labelHalo` lightened when a theme or the `colors.labelHalo` knob sets it, else white
   * on a light style and dark grey on a dark one.
   */
  color?: string;
  /**
   * The label naming the countries.
   */
  label?: CountryCrossingLabelConfig;
};
/**
 * The label in a border crossing bubble.
 *
 * @group Routing
 */
type CountryCrossingLabelConfig = {
  /**
   * The label colour.
   *
   * @defaultValue the map's label colour when a theme sets it and the bubble has no
   * {@link CountryCrossingConfig.color}, else black or white, whichever reads on the bubble.
   */
  color?: string;
};
/**
 * A piece of route information a summary bubble can show.
 *
 * - `duration` - The travel time, traffic included.
 * - `distance` - The route's length, in the display units.
 * - `durationDifference` - How much longer or shorter the route takes than the selected one, such
 *   as `+6 min`. Only the other routes show it, and only when the difference rounds to a minute.
 * - `trafficDelay` - The summary's `trafficDelayInSeconds`, the delay of the traffic events along
 *   the route, on a line of its own beside an icon coloured by the worst delay along the route.
 *   Only a route with a delay shows it.
 *
 * @group Routing
 */
type SummaryBubbleField = 'duration' | 'distance' | 'durationDifference' | 'trafficDelay';
/**
 * Which routes the summary bubbles show on.
 *
 * - `all` - Every route shown.
 * - `selected` - The selected route alone.
 * - `alternatives` - Every route but the selected one, for an app that already tells the selected
 *   trip in a panel or a popup of its own.
 *
 * @group Routing
 */
type SummaryBubbleRoutes = 'all' | 'selected' | 'alternatives';
/**
 * The text of the route summary bubbles: its size, colour, opacity, typeface and what it says.
 *
 * @remarks
 * The bubble is the text's background, so the text takes no halo. A `title` replaces the text
 * {@link SummaryBubblesConfig.fields} builds. A function title is called for each route when the
 * routes are shown, when another is selected and when the display units change. A route it returns
 * an empty string for gets no bubble.
 *
 * @example
 * ```typescript
 * const label: SummaryBubbleLabelConfig = {
 *   title: (summary) => `${summary.properties.formattedDuration} · ${summary.properties.formattedDistance}`,
 *   typeface: 'sans-italic',
 * };
 * ```
 *
 * @group Routing
 */
type SummaryBubbleLabelConfig = Omit<FeatureLabelConfig<DisplayRouteSummary>, 'color' | 'haloColor' | 'haloWidth' | 'font'> & {
  /**
   * The text colour on the selected route's bubble. The deselected routes' bubbles keep their
   * muted text, as their lines keep their grey.
   *
   * @defaultValue the map's label colour when a theme sets it and the bubble has no
   * {@link SummaryBubblesConfig.color}, else black or white, whichever reads on the bubble.
   */
  color?: string;
};
/**
 * The route summary bubbles: what they say, from which zoom they show and how they look.
 *
 * @remarks
 * - Each route shown gets one bubble, or the ones {@link SummaryBubblesConfig.routes} picks, on its
 *   longest distinct section: the stretch no other route drives, so routes sharing most of their way
 *   keep their bubbles apart.
 * - A route with no distinct section as long as 5% of it uses its whole length.
 * - A bubble stays put when another route is selected or `routes` changes.
 * - It reads the routes' `sections.distinct`, comparing the routes itself only when one lacks them.
 *   So show one response's routes, all of them: sections found against other routes can put a bubble
 *   on a road they share.
 * - Unset colours follow the map: a theme's label halo and label colours ({@link TomTomMap.mapColors})
 *   once one sets them, else white on a light style and dark grey on a dark one. The deselected
 *   routes' bubbles take a shade darker.
 *
 * @example
 * ```typescript
 * const summaryBubbles: SummaryBubblesConfig = {
 *   routes: 'alternatives',
 *   fields: ['durationDifference', 'trafficDelay'],
 *   maxZoom: 13,
 *   color: '#1A2024',
 * };
 * ```
 *
 * @group Routing
 */
type SummaryBubblesConfig = {
  /**
   * Whether the route summary bubbles show on the map.
   *
   * @defaultValue true
   */
  visible?: boolean;
  /**
   * Which routes get a bubble.
   *
   * @defaultValue `'all'`
   */
  routes?: SummaryBubbleRoutes;
  /**
   * What each bubble says, in order.
   *
   * @remarks
   * The first field a route carries is written in bold and the ones after it follow, muted, so
   * with `durationDifference` first the selected route leads with the next field. `trafficDelay`
   * goes on its own line, wherever it is listed. A bubble with nothing to say is not drawn, so
   * `['trafficDelay']` shows bubbles only on the routes with a delay,
   * `['durationDifference']` only on the routes other than the selected one, and `[]` none.
   *
   * @defaultValue `['duration', 'distance', 'trafficDelay']`
   */
  fields?: SummaryBubbleField[];
  /**
   * The lowest zoom the bubbles are drawn at.
   *
   * @defaultValue every zoom
   */
  minZoom?: number;
  /**
   * The zoom from which the bubbles stop being drawn, for bubbles that summarise the routes from
   * afar and leave as you zoom in to inspect them.
   *
   * @defaultValue every zoom
   */
  maxZoom?: number;
  /**
   * The colour of the selected route's bubble. The deselected routes' bubbles take a darker
   * shade of it, and the text whichever of black and white reads on it.
   *
   * @defaultValue the map's `labelHalo` lightened, when a theme or the `colors.labelHalo` knob sets
   * it; else white on a light style, dark grey on a dark one
   */
  color?: string;
  /**
   * The bubbles' text.
   */
  label?: SummaryBubbleLabelConfig;
};
/**
 * The highlights the routes draw: a hovered or clicked route widens its outline in the outline
 * colour, and a focused section is ringed clear of every line the route draws.
 *
 * @remarks
 * The routes draw their event states once a handler covers them, or
 * {@link RoutingModule.setEventState} puts one. {@link RoutingModule.selectRoute} clears a route's
 * `click` state, since the selected style marks the route from then on. A `layers.mainLines` outline
 * `line-width` is drawn as given instead. The sections {@link RoutingModule.setSectionFocus} marks draw the `section`
 * highlight.
 *
 * @group Routing
 */
type RouteHighlightConfig = {
  /** The hovered or clicked route's outline. */
  outline?: {
    /**
     * Multiplier on the outline width, where `1` draws it as on any other route.
     *
     * @remarks
     * Clamped to 1 to 1.25, its `range` in {@link routingKnobCatalogue}.
     *
     * @defaultValue `1.2`
     */
    widthFactor?: number;
  };
  /** The focused sections, ringed on both sides of the route without covering what it draws. */
  section?: {
    /** The ring, which runs clear of the widest line the route draws: its hovered outline or a section. */
    outline?: {
      /**
       * The ring's colour.
       *
       * @defaultValue `#000` on light map styles, `#FFF` on dark styles
       */
      color?: string;
      /**
       * Multiplier on the ring's width, which grows from 2 to 4 pixels as the zoom grows.
       *
       * @remarks
       * Clamped to 0.5 to 2, its `range` in {@link routingKnobCatalogue}.
       *
       * @defaultValue `1`
       */
      widthFactor?: number;
    };
  };
};
/**
 * Appearance of one route section type.
 *
 * @remarks
 * The semantic tier for sections. It lets you draw, recolour, resize or mute any section type the
 * module draws without writing a MapLibre layer spec. {@link DrawnSectionType} lists the types,
 * and `layers.sections` takes anything these knobs cannot express.
 *
 * Which knobs a type takes is part of its type. `traffic` colours its line by `magnitudeOfDelay`
 * and takes its icons from the incident data, so `sections.traffic.color` does not compile rather
 * than compiling and drawing nothing. {@link sectionSupportsKnob} answers the same question at
 * runtime, for a UI that builds its controls from the type.
 *
 * @example
 * ```typescript
 * const config: RoutingModuleConfig = {
 *   sections: {
 *     // Opt in to two of the sections nothing draws by default:
 *     urban: { visible: true },
 *     unpaved: { visible: true, color: '#8B5A2B', opacity: 0.8 },
 *     // Restyle three that are drawn already:
 *     lowEmissionZone: { color: '#1B7A43' },
 *     tunnel: { color: '#402060', style: 'halo' },
 *     tollRoad: { icon: { image: 'poi-toll_plaza', placement: 'along' } },
 *     // And drop one:
 *     traffic: { visible: false },
 *   },
 * };
 * ```
 *
 * @group Routing
 */
type SectionDisplayConfig<T extends DrawnSectionType = DrawnSectionType> = Pick<SectionKnobs, SectionKnobOf<T>>;
/**
 * Appearance of every route section type, keyed by type.
 *
 * @group Routing
 */
type SectionsDisplayConfig = { [T in DrawnSectionType]?: SectionDisplayConfig<T>; };
/**
 * Where the route's layers sit in the map's layer stack, with one target for the whole route or one
 * per part of it.
 *
 * @remarks
 * The parts, and where each sits by default:
 * - `mainLines` - The route lines, with every section line (the bands drawn under the route line
 *   and the stretches drawn over it). Below the map's labels.
 * - `instructionLines` - The guidance lines and their arrows. Below the map's labels, above the
 *   route lines.
 * - `icons` - Every icon the route draws: waypoints, summary bubbles, border crossings and
 *   section icons. Above the map's labels, the tunnel sign and the icons generated
 *   section types ask for lowest among them. A target puts them all beneath it, in that order.
 *
 * Each part keeps its own layers' order wherever it goes. Section signs are not a part: their
 * {@link SectionSignConfig.priority} settles which symbols they give way to, among the route icons
 * and the map labels wherever this put them.
 *
 * @example
 * ```typescript
 * // The whole route on top of the map
 * const everything: RoutingBeforeLayerConfig = 'top';
 * // Route lines under the road network, icons where they are
 * const lines: RoutingBeforeLayerConfig = { mainLines: 'lowestRoadLine' };
 * ```
 *
 * @group Routing
 */
type RoutingBeforeLayerConfig = PartsBeforeLayerConfig<'mainLines' | 'instructionLines' | 'icons'>;
/**
 * Configuration options for the routing module.
 *
 * @remarks
 * It customises how routes look and behave, including display units,
 * waypoint handling and layer styling.
 *
 * @see {@link RoutingModuleSerializableConfig} for the part that survives JSON.
 *
 * @group Routing
 */
type RoutingModuleConfig = MapModuleCommonConfig & {
  /**
   * Whether the module draws anything: route lines, waypoints, sections, guidance, summary bubbles
   * and border crossings.
   *
   * @remarks
   * `showRoutes()`, `showWaypoints()` and the clear methods never change it. A hidden module keeps
   * its data until {@link RoutingModule.setVisible} shows it again. While shown, each part's own
   * `visible` (`sections.<type>.visible`, `summaryBubbles.visible`, …) still decides whether it draws.
   *
   * @defaultValue true
   */
  visible?: boolean;
  /**
   * Units of the distances and durations the module writes on the map.
   *
   * @remarks
   * They apply over the global configuration's display units field by field, and a field left
   * unset keeps the global value. `distance.type` picks the unit system (`metric`, `imperial_us`
   * or `imperial_uk`), and the other fields relabel the units.
   *
   * @defaultValue the global configuration's `displayUnits`
   */
  displayUnits?: DisplayUnits;
  /**
   * The colour of the route line, its outline and the waypoint icons, as any CSS colour string.
   *
   * @remarks
   * The outline takes a darker shade of it. When unset, the map's accent colour applies if a
   * theme sets one ({@link TomTomMap.mapColors}), otherwise the SDK's own route blue. `layers` overrides
   * it layer by layer.
   */
  color?: string;
  /**
   * Thickness preset of the route line and its outline, which the section and instruction lines
   * follow.
   *
   * @defaultValue `"m"`
   */
  widthPreset?: RouteWidth;
  /**
   * Multiplier over the {@link widthPreset}, where `1` leaves it unchanged. The two compose, so
   * `{ widthPreset: 'l', widthFactor: 1.5 }` draws 1.5 × the `"l"` profile.
   *
   * @remarks
   * Clamped to 0.5 to 2, its `range` in {@link routingKnobCatalogue}. Sections without a `widthFactor` of
   * their own follow it, and so do the instruction arrows, which no preset resizes.
   *
   * @defaultValue `1`
   */
  widthFactor?: number;
  /**
   * Opacity of the route lines and their outlines, selected and deselected, from 0 to 1.
   *
   * @remarks
   * Lower it to keep what the map draws under a route readable, such as traffic flow. Sections
   * keep their own `sections.<type>.opacity`, and the waypoints and summary bubbles stay opaque.
   *
   * @defaultValue `1`
   */
  opacity?: number;
  /**
   * How a hovered or clicked route is drawn.
   */
  highlight?: RouteHighlightConfig;
  /**
   * Configuration for the waypoints source and layers to display them on the map.
   *
   * @remarks
   * It controls how waypoint source data and layer configs are processed to render them on the map.
   */
  waypoints?: WaypointsConfig;
  /**
   * The route summary bubbles on the map.
   *
   * @remarks
   * A summary bubble shows key route information (duration, distance, traffic delay)
   * as a visual overlay along the route.
   */
  summaryBubbles?: SummaryBubblesConfig;
  /**
   * Appearance of the border crossings along the route.
   *
   * @remarks
   * They come from the route's `country` sections, so a route carrying none draws none.
   */
  countryCrossings?: CountryCrossingConfig;
  /**
   * Appearance of the route sections, keyed by section type.
   *
   * @remarks
   * It covers every section type the module draws: draw it or not, its colour, opacity, width,
   * whether it bands the route or stands in for its line, its line pattern, its icon and its sign.
   * A type takes only the knobs it can honour, so `traffic` has no colour, pattern or icon.
   *
   * Some types draw themselves and the rest only when you switch them on, as
   * {@link SectionDisplayConfig.visible} lists.
   *
   * `layers.sections` takes MapLibre overrides for the same types, for anything these knobs
   * cannot express.
   */
  sections?: SectionsDisplayConfig;
  /**
   * Where the route's layers sit in the map's layer stack, for the whole route or per part.
   *
   * @remarks
   * If you leave it out, every layer sits where {@link RoutingBeforeLayerConfig} says it does by
   * default.
   */
  beforeLayerConfig?: RoutingBeforeLayerConfig;
  /**
   * MapLibre overrides for the route's layers, for what the other settings can't express.
   *
   * @remarks
   * Each entry is a partial layer spec merged onto the layer the module builds from the rest of
   * this configuration. Top-level fields replace, and `paint` and `layout` merge per property, so
   * set only what you change. Any layer you don't name keeps its look.
   *
   * Don't copy values from {@link defaultRoutingLayers} into an entry. They come from the default
   * configuration, so they write the default `line-width` over the one `widthPreset` and
   * `widthFactor` computed, and the same for every other setting.
   */
  layers?: RouteLayersConfig;
};
/**
 * The part of a {@link RoutingModuleConfig} that survives JSON, for saving
 * `getConfig()` and replaying it with `applyConfig()`.
 *
 * @remarks
 * It leaves out what JSON cannot carry, which a replay adds back in code:
 * - `waypoints.icon.mapping`, and `waypoints.label.title` and `summaryBubbles.label.title` as a
 *   function. A MapLibre expression title serialises.
 * - Any image given as an `HTMLImageElement`, in `waypoints.icon.customIcons` and each waypoint
 *   role's `image`. See {@link SerializableCustomImage}.
 *
 * @group Routing
 */
type RoutingModuleSerializableConfig = Omit<RoutingModuleConfig, 'waypoints' | 'summaryBubbles'> & {
  waypoints?: Omit<WaypointsConfig, 'icon' | 'label'> & {
    icon?: Omit<WaypointIconConfig, WaypointIndexType | 'customIcons' | 'mapping'> & { [R in WaypointIndexType]?: SerializablePinIconConfig; } & {
      customIcons?: SerializableCustomImage[];
    };
    label?: SerializableFeatureLabelConfig<WaypointLabelConfig>;
  };
  summaryBubbles?: Omit<SummaryBubblesConfig, 'label'> & {
    label?: SerializableFeatureLabelConfig<SummaryBubbleLabelConfig>;
  };
};
//#endregion
//#region src/routing/types/routingKnobs.d.ts
/**
 * The id of a routing knob, its path into {@link RoutingModuleConfig}, such as `widthFactor` or
 * `sections.tunnel.color`. See {@link routingKnobCatalogue} for what each one does.
 *
 * @remarks
 * Each section type contributes only the knobs {@link SectionKnobOf} lists for it.
 *
 * @group Routing
 */
type RoutingKnobId = 'visible' | 'color' | 'widthPreset' | 'widthFactor' | 'opacity' | `highlight.outline.${keyof NonNullable<RouteHighlightConfig['outline']>}` | `highlight.section.${LeafPathOf<NonNullable<RouteHighlightConfig['section']>>}` | 'waypoints.sizePreset' | 'waypoints.sizeFactor' | `waypoints.icon.style.${keyof SVGIconStyleOptions}` | `waypoints.icon.${WaypointIndexType}.style.${keyof SVGIconStyleOptions}` | 'waypoints.stopNumbering' | `waypoints.label.${Exclude<keyof WaypointLabelConfig, 'title' | 'customTypeface'>}` | `waypoints.highlight.${keyof WaypointHighlightConfig}` | 'waypoints.entryPoints' | `displayUnits.distance.${keyof DistanceDisplayUnits}` | `displayUnits.time.${keyof TimeDisplayUnits}` | `summaryBubbles.${Exclude<keyof SummaryBubblesConfig, 'label'>}` | `summaryBubbles.label.${Exclude<keyof SummaryBubbleLabelConfig, 'title' | 'customTypeface'>}` | `countryCrossings.${Exclude<keyof CountryCrossingConfig, 'label'>}` | `countryCrossings.label.${keyof CountryCrossingLabelConfig}` | { [T in DrawnSectionType]: `sections.${T}.${LeafPathOf<SectionDisplayConfig<T>>}`; }[DrawnSectionType];
/**
 * The plain value type that a routing knob's path holds in {@link RoutingModuleConfig}.
 *
 * @group Routing
 */
type RoutingKnobValueOf<ID extends RoutingKnobId> = KnobPlainValue<ValueAt<RoutingModuleConfig, ID>>;
/**
 * One entry of {@link routingKnobCatalogue}. The value in force is the one at its path in
 * {@link RoutingModule.getConfig}, otherwise its `default`. If there is neither, the style or the
 * global config decides.
 *
 * @group Routing
 */
type RoutingKnob = KnobEntry<RoutingKnobId, Exclude<KnobKind, 'offset' | 'colors'>>;
//#endregion
//#region src/routing/knobCatalogue.d.ts
/**
 * Every routing knob with its kind, description, range or options and, where one value holds
 * everywhere, its default. Route-wide knobs come first, then each drawn section type's. It's
 * static data, readable with no map loaded.
 *
 * @remarks
 * Knobs are plain display values in {@link RoutingModuleConfig}, at the paths their ids name.
 * `layers`, `beforeLayerConfig`, the waypoint images, icon mapping and label title, which take
 * structured, function or MapLibre values, and `events` aren't knobs. A `displayUnits` knob left
 * unset follows the global config.
 *
 * @group Routing
 */
export declare const routingKnobCatalogue: readonly RoutingKnob[];
/**
 * Every routing knob id, in catalogue order.
 *
 * @group Routing
 */
export declare const routingKnobIds: readonly RoutingKnobId[];
//#endregion
//#region src/routing/layers/routingLayers.d.ts
/**
 * The layers {@link RoutingModule} draws with its default configuration, on a light style that no
 * theme or knob has recoloured.
 *
 * @remarks
 * It covers every route layer: the route lines, waypoints, sections, guidance lines, summary
 * bubbles and border crossings. Read it to find a layer's name and what it paints by default, not
 * to spread into {@link RoutingModuleConfig.layers}, which says why.
 *
 * The module builds its own layers per map, so on a dark style, under a theme or with a map
 * typeface, the colours and fonts it draws differ from these.
 *
 * @see {@link RouteLayersConfig} for the configuration type definition
 * @see {@link RoutingModule.create} for initialization options
 * @see {@link RoutingModule.applyConfig} for runtime configuration updates
 *
 * @group Routing
 */
export declare const defaultRoutingLayers: Required<RouteLayersConfig>;
//#endregion
//#region src/routing/layers/shared.d.ts
/**
 * The layer filter that keeps the selected route's features, so a layer draws only that route.
 * @group Routing
 */
export declare const SELECTED_ROUTE_FILTER: ExpressionSpecification;
/**
 * The layer filter that keeps the deselected routes' features, so a layer draws only those.
 * @group Routing
 */
export declare const DESELECTED_ROUTE_FILTER: ExpressionSpecification;
