//#region src/routing/types/showOptions.d.ts
/**
 * Optional parameters for showing routes on the map.
 *
 * They control which route is initially selected when you display multiple route
 * alternatives.
 *
 * @remarks
 * When multiple routes are displayed, such as fastest and shortest, one is typically
 * shown as "selected" (highlighted) and the others as "deselected" (dimmed). This type
 * controls which route gets the selected state.
 *
 * @example
 * ```typescript
 * // Show first route as selected (default)
 * const options: ShowRoutesOptions = {
 *   selectedIndex: 0
 * };
 *
 * // Show second route as selected
 * const altOptions: ShowRoutesOptions = {
 *   selectedIndex: 1
 * };
 *
 * // Use default (first route selected)
 * const defaultOptions: ShowRoutesOptions = {};
 * ```
 *
 * @group Routing
 */
type ShowRoutesOptions = {
  /**
   * The index of the route within the array of routes to show as selected.
   *
   * @remarks
   * It is zero-based, matching the position in the routes array. The selected route
   * displays with full colour and prominence, and the other routes are dimmed to show
   * they are alternatives.
   *
   * @default 0 (the first route is shown as selected)
   *
   * @example
   * ```typescript
   * selectedIndex: 0  // First route (usually fastest)
   * selectedIndex: 1  // Second route (usually alternative)
   * selectedIndex: 2  // Third route
   * ```
   */
  selectedIndex?: number;
};
//#endregion
//#region src/routing/RoutingModule.d.ts
/**
 * The routes or waypoints just rendered, as `routing.events.on('shown-features', ...)` receives them.
 *
 * @group Routing
 */
export type RoutingShownFeatures = {
  routes: Route | Routes;
} | {
  waypoints: PlanningWaypoint[] | Waypoints;
};
/**
 * The module's own events of {@link RoutingModule}, plus one named scope per part of a route it
 * draws.
 *
 * @group Routing
 */
